 r={"file":str(out),"sha256":sha(out),"action":"attack","direction":"E","frame":int(num),"durationMs":30,"pivot":[0.5,0.08],"targetFootPoint":[512,942],"generatedAt":receipt["completedAt"],"generationStartedAt":receipt["startedAt"],"tool":"image_gen.imagegen","route":"builtin","configSnapshot":json.loads(Path(r"D:/work/image/config/image-generation.json").read_text(encoding="utf-8")),"submittedParameters":{"model":None,"quality":None,"transparent_background":True,"referenced_image_paths":receipt["references"]},"actualModel":None,"actualQuality":None,"unverifiedReason":"Host managed; no model/quality selector and no model/quality returned by built-in tool.","evidence":{"receipt":str(rp),"disclosedFields":["output_hint"]},"prompt":receipt["promptFile"],"references":refs,"native":native,"nativeSourcePath":str(src),"export":{"width":1024,"height":1024,"format":"PNG","mode":"RGBA","sha256":sha(out),"alphaExtrema":a.getextrema(),"alphaBounds":a.getbbox(),"opaqueBounds":a.point(lambda x:255 if x>=128 else 0).getbbox()},"derivedFrom":{"path":str(src),"sha256":native["sha256"]},"operation":"Whole-canvas uniform 1254-to-1024 PNG RGBA export only. No crop, translation, per-frame alignment, mirroring, duplication or interpolation; pose correction generated by built-in AI.","visualReview":{"status":"viewed","notes":note},"runtimeIntegration":"not tested","repairAttempt":int(attempt)}
